// emu_top.v -- Zybo (xc7z010clg400-1) top for TEMPO-32 FPGA emulation.
//
// Clocking: 125 MHz board clock (pin L16, from the Ethernet PHY) ->
//   MMCM -> single test clock at the frequency chosen at build time
//   (see fpga/clk_config.vh, generated by build.tcl from FREQ).
// VIO + ILA run on the fixed 125 MHz input clock so they stay alive
// and give a heartbeat diagnostic (probe_in2) even if the test clock dies.
//
// One bitstream per frequency (50/100/125/150 MHz); the hardware sweep
// programs each bitstream in turn (see fpga/program.tcl, test_freq.tcl).
//
// Debug: VIO (start_test, reset, inject_fault in;
//          status word, signature, clock heartbeats out),
//        ILA (loader state + milestones, uio_out, hp_tx/hp_rx, test clock).
//
// FPGA-EMULATION-ONLY. Not for ASIC synthesis.
//
// SPDX-License-Identifier: Apache-2.0
`default_nettype none

module emu_top (
    input wire clk125_p   // 125 MHz board clock, pin L16
);

    // ------------------------------------------------------------------
    // Clock input
    // ------------------------------------------------------------------
    wire clk125_raw;
    IBUF ibuf_125 (.I(clk125_p), .O(clk125_raw));

    // ------------------------------------------------------------------
    // MMCM: 125 MHz -> test clock at the frequency selected by
    // fpga/clk_config.vh (generated by build.tcl from the FREQ argument).
    // VCO and dividers are chosen per frequency; see build.tcl.
    // ------------------------------------------------------------------
    `include "clk_config.vh"
    wire test_clk_m;
    wire clkfb_pre, clkfb;
    wire mmcm_locked;

    MMCME2_ADV #(
        .CLKIN1_PERIOD   (8.0),
        .CLKFBOUT_MULT_F (`CLKFBOUT_MULT_F),
        .DIVCLK_DIVIDE   (1),
        .CLKOUT0_DIVIDE_F(`CLKOUT0_DIVIDE_F),
        .COMPENSATION    ("ZHOLD"),
        .BANDWIDTH       ("OPTIMIZED")
    ) mmcm (
        .CLKIN1    (clk125_raw),
        .CLKIN2    (1'b0),
        .CLKINSEL  (1'b1),
        .CLKFBIN   (clkfb),
        .CLKFBOUT  (clkfb_pre),
        .CLKOUT0   (test_clk_m),
        .LOCKED    (mmcm_locked),
        .PWRDWN    (1'b0),
        .RST       (1'b0),
        .CLKOUT1   (), .CLKOUT2   (), .CLKOUT3   (), .CLKOUT4   (),
        .CLKOUT5   (), .CLKOUT6   (),
        .CLKFBOUTB (), .CLKFBSTOPPED(), .CLKINSTOPPED(),
        .DO(), .DRDY(), .PSDONE()
    );
    BUFG bufg_fb  (.I(clkfb_pre),  .O(clkfb));
    wire test_clk;
    BUFG bufg_test(.I(test_clk_m),  .O(test_clk));
    wire clk125_b;
    BUFG bufg_125 (.I(clk125_raw), .O(clk125_b));

    // ------------------------------------------------------------------
    // VIO (runs on fixed 125 MHz). All probe_out are 1 bit so TCL
    // OUTPUT_VALUE is unambiguous 0/1.
    // ------------------------------------------------------------------
    wire        vio_start_test;
    wire        vio_reset;
    wire        vio_inject_fault;
    wire [31:0] vio_status;
    wire [31:0] vio_signature;
    wire [31:0] vio_heartbeats;

    vio_0 u_vio (
        .clk       (clk125_b),
        .probe_in0 (vio_status),
        .probe_in1 (vio_signature),
        .probe_in2 (vio_heartbeats),
        .probe_out0(vio_start_test),
        .probe_out1(vio_reset),
        .probe_out2(vio_inject_fault)
    );

    // ------------------------------------------------------------------
    // Synchronizers into the test-clock domain; async-assert on !locked.
    // ------------------------------------------------------------------
    (* ASYNC_REG = "TRUE" *) reg [1:0] sync_start_a, sync_start_b;
    (* ASYNC_REG = "TRUE" *) reg [1:0] sync_rst_a, sync_rst_b;
    (* ASYNC_REG = "TRUE" *) reg [1:0] sync_fault_a, sync_fault_b;

    // synchronizers live in the test_clk domain; async-assert on !locked
    always @(posedge test_clk or negedge mmcm_locked) begin
        if (!mmcm_locked) begin
            sync_start_a <= 2'b00; sync_start_b <= 2'b00;
            sync_rst_a <= 2'b00; sync_rst_b <= 2'b00;
            sync_fault_a <= 2'b00; sync_fault_b <= 2'b00;
        end else begin
            sync_start_a <= {1'b0, vio_start_test}; sync_start_b <= sync_start_a;
            sync_rst_a <= {1'b0, vio_reset};       sync_rst_b <= sync_rst_a;
            sync_fault_a <= {1'b0, vio_inject_fault}; sync_fault_b <= sync_fault_a;
        end
    end
    wire loader_start_test = sync_start_b[0];
    wire loader_inject    = sync_fault_b[0];

    // loader_rst_n: async assert on !mmcm_locked, sync deassert; also forced
    // low (sync) while the VIO reset bit is set. Registered so the loader's
    // async-reset deassertion is synchronous to test_clk.
    reg loader_rst_n_r;
    always @(posedge test_clk or negedge mmcm_locked) begin
        if (!mmcm_locked) loader_rst_n_r <= 1'b0;
        else             loader_rst_n_r <= ~sync_rst_b[0];
    end
    wire loader_rst_n = loader_rst_n_r;

    // ------------------------------------------------------------------
    // DUT (unmodified ASIC RTL) + tb_top pad model
    // ------------------------------------------------------------------
    wire        hp_rx;
    wire        hp_tx;
    wire [7:0]  uio_out_w, uio_oe_w;
    wire [7:0]  uio_in_w;
    wire [7:0]  uo_bus;
    wire        phase_reset;
    wire        dut_rst_n;

    assign dut_rst_n = loader_rst_n & ~phase_reset;
    assign uio_in_w  = uio_oe_w & uio_out_w;  // tb_top pad model

    tt_um_pemu u_dut (
        .ui_in  ({7'b0, hp_rx}),
        .uo_out (uo_bus),
        .uio_in (uio_in_w),
        .uio_out(uio_out_w),
        .uio_oe (uio_oe_w),
        .ena    (1'b1),
        .clk    (test_clk),
        .rst_n  (dut_rst_n)
    );
    assign hp_tx = uo_bus[0];

    // ------------------------------------------------------------------
    // Loader
    // ------------------------------------------------------------------
    wire [15:0] milestones;
    wire [7:0]  fail_code;
    wire        phaseA_pass, phaseB_pass, loader_done;
    wire [31:0] signature;
    wire [7:0]  loader_st;
    wire        tx_busy_w, rx_valid_w;

    emu_loader u_loader (
        .clk         (test_clk),
        .rst_n       (loader_rst_n),
        .hp_rx       (hp_rx),
        .hp_tx       (hp_tx),
        .uio_out     (uio_out_w),
        .phase_reset (phase_reset),
        .start_test  (loader_start_test),
        .inject_fault(loader_inject),
        .milestones  (milestones),
        .fail_code   (fail_code),
        .phaseA_pass (phaseA_pass),
        .phaseB_pass (phaseB_pass),
        .done        (loader_done),
        .signature   (signature),
        .st          (loader_st),
        .tx_busy_o   (tx_busy_w),
        .rx_valid_o  (rx_valid_w)
    );

    // ------------------------------------------------------------------
    // Clock-domain crossing into the 125 MHz VIO/ILA domain.
    // Status/signature are static once loader_done, so a 2-FF resync is
    // plenty; heartbeats prove both clocks toggle.
    // ------------------------------------------------------------------
    reg [31:0] status_q1, status_q2;
    reg [31:0] sig_q1, sig_q2;
    reg [15:0] test_cnt, test_cnt_q1, test_cnt_q2;
    reg [15:0] clk125_cnt;

    wire [31:0] status_w = {phaseA_pass, phaseB_pass, 6'b0, fail_code, milestones};

    always @(posedge test_clk or negedge mmcm_locked) begin
        if (!mmcm_locked) test_cnt <= 16'd0;
        else test_cnt <= test_cnt + 16'd1;
    end
    always @(posedge clk125_b) begin
        clk125_cnt <= clk125_cnt + 16'd1;
        status_q1 <= status_w;   status_q2 <= status_q1;
        sig_q1    <= signature;   sig_q2    <= sig_q1;
        test_cnt_q1 <= test_cnt; test_cnt_q2 <= test_cnt_q1;
    end
    assign vio_status     = status_q2;
    assign vio_signature  = sig_q2;
    assign vio_heartbeats = {clk125_cnt, test_cnt_q2};

    // ------------------------------------------------------------------
    // ILA (125 MHz domain; test-clock-domain signals resync'd for display)
    // ------------------------------------------------------------------
    reg [15:0] ms_q1, ms_q2;
    reg [7:0]  st_q1, st_q2;
    reg [7:0]  uio_q1, uio_q2;
    reg        hp_tx_q1, hp_tx_q2, hp_rx_q1, hp_rx_q2;
    reg        tclk_q1, tclk_q2, drst_q1, drst_q2;
    reg        rxv_q1, rxv_q2, txb_q1, txb_q2, done_q1, done_q2;

    always @(posedge clk125_b) begin
        ms_q1 <= milestones; ms_q2 <= ms_q1;
        st_q1 <= loader_st;   st_q2 <= st_q1;
        uio_q1 <= uio_out_w;  uio_q2 <= uio_q1;
        hp_tx_q1 <= hp_tx; hp_tx_q2 <= hp_tx_q1;
        hp_rx_q1 <= hp_rx; hp_rx_q2 <= hp_rx_q1;
        tclk_q1 <= test_clk; tclk_q2 <= tclk_q1;
        drst_q1 <= dut_rst_n; drst_q2 <= drst_q1;
        rxv_q1 <= rx_valid_w; rxv_q2 <= rxv_q1;
        txb_q1 <= tx_busy_w;  txb_q2 <= txb_q1;
        done_q1 <= loader_done; done_q2 <= done_q1;
    end

    ila_0 u_ila (
        .clk   (clk125_b),
        .probe0({ms_q2, st_q2}),                       // 24b: milestones + loader state
        .probe1(uio_q2),                               // 8b : uio_out pins
        .probe2({1'b0, hp_tx_q2, hp_rx_q2, tclk_q2,     // 8b : misc
                 drst_q2, rxv_q2, txb_q2, done_q2})
    );

endmodule
`default_nettype wire
